  2	 * Integration tests for ledger_get_repository_context tool.
  3	 *
  4	 * Tests drive the tool handler directly via _internal, using vi.mock to
  5	 * redirect resolveLedgerRoot() and deriveRepoName() to controlled values
  6	 * so the real ledger storage is never touched.
  7	 */
  8	import { vi, describe, it, expect, beforeEach, afterEach } from 'vitest';
  9	import { mkdtemp, rm, mkdir, writeFile } from 'fs/promises';
 10	import { join } from 'path';
 11	import { tmpdir } from 'os';
 12	
 13	// ─── Module-level variable updated by beforeEach ──────────────────────────
 14	let tempLedgerRoot: string;
 15	
 16	vi.mock('../../src/utils/ledger-root.js', () => ({
 17	  resolveLedgerRoot: () => tempLedgerRoot,
 18	  WORKSPACE_ROOT: '/fake/workspace',
 19	  ORCHESTRATOR_LOGS_DIR: '/fake/workspace/orchestrator/logs',
 20	  projectSlugFromPath: (p: string) => (p.split('/').pop() ?? 'unknown'),
 21	  inferProjectRootFromPlanPath: (p: string) => {
 22	    // Walk up 4 dirs from the plan path
 23	    const parts = p.split('/');
 24	    return parts.slice(0, parts.length - 4).join('/') || '/';
 25	  },
 26	  deriveRepoName: (_planPath: string) => 'my-repo',
 27	}));
 28	
 29	import { _internal } from '../../src/tools/repository-context.js';
 30	
 31	const { getRepositoryContext } = _internal;
 32	
 33	// ─── Helpers ──────────────────────────────────────────────────────────────
 34	
 35	function parseResult(result: { content: Array<{ type: string; text: string }> }) {
 36	  return JSON.parse(result.content[0]!.text);
 37	}
 38	
 39	function isError(result: { isError?: boolean }) {
 40	  return result.isError === true;
 41	}
