 43	/**
 44	 * Seeds a minimal .meta.json for a project at:
 45	 * {tempLedgerRoot}/{folder}/{slug}/.meta.json
 46	 */
 47	async function seedProject(
 48	  folder: string,
 49	  slug: string,
 50	  overrides: Record<string, unknown> = {}
 51	): Promise<void> {
 52	  const dir = join(tempLedgerRoot, folder, slug);
 53	  await mkdir(dir, { recursive: true });
 54	  const meta = {
 55	    slug,
 56	    plan_path: `/fake/${folder}/docs/agents/plans/${slug}`,
 57	    status: 'COMPLETE',
 58	    date_created: overrides.date_created ?? '2026-01-01T00:00:00Z',
 59	    last_updated: overrides.last_updated ?? '2026-01-01T00:00:00Z',
 60	    ...overrides,
 61	  };
 62	  await writeFile(join(dir, '.meta.json'), JSON.stringify(meta, null, 2), 'utf-8');
 63	}
