 65	/**
 66	 * Seeds .repositories.json in the ledger root.
 67	 */
 68	async function seedRegistry(data: unknown): Promise<void> {
 69	  await writeFile(
 70	    join(tempLedgerRoot, '.repositories.json'),
 71	    JSON.stringify(data, null, 2),
 72	    'utf-8'
 73	  );
 74	}
