  1	import { z } from 'zod';
  2	import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
  3	import { LedgerStore } from '../storage/ledger-store.js';
  4	import { loadRegistry, findByFolderName } from '../storage/repository-registry.js';
  5	import { KnowledgeStoreManager } from '../storage/knowledge-store.js';
  6	import { resolveLedgerRoot, deriveRepoName } from '../utils/ledger-root.js';
  7	import type { ProjectMeta } from '../schema/project-meta.js';
  8	import type { RepositoryEntry } from '../schema/repository-registry.js';
  9	import type { Insight } from '../schema/knowledge.js';
 10	
 11	// ─── Input Schema ─────────────────────────────────────────────────────────
 12	
 13	const GetRepositoryContextSchema = z.object({
 14	  cwd_path: z
 15	    .string()
 16	    .optional()
 17	    .describe(
 18	      'Absolute path to the workspace root directory. Used to derive the repository name ' +
 19	      'when repository_name is not provided. Ignored when repository_name is supplied.'
 20	    ),
 21	  repository_name: z
 22	    .string()
 23	    .optional()
 24	    .describe(
 25	      'Explicit repository name to look up in the registry. When provided, cwd_path ' +
 26	      'is not used for name derivation. Treated as both the ledger folder name and the ' +
 27	      'registry lookup key.'
 28	    ),
 29	  include_insights: z
 30	    .boolean()
 31	    .optional()
 32	    .default(true)
 33	    .describe(
 34	      'When true (default), the response includes relevant_insights[] queried from the ' +
 35	      'knowledge store. Set to false to return an empty relevant_insights[] array and reduce response size.'
 36	    ),
 37	  max_projects: z
 38	    .number()
 39	    .int()
 40	    .positive()
 41	    .optional()
 42	    .default(5)
 43	    .describe(
 44	      'Maximum number of projects to return in the projects[] array, sorted by date_created ' +
 45	      'descending (most recent first). Defaults to 5.'
 46	    ),
 47	});
