 49	// ─── Response Shape ───────────────────────────────────────────────────────
 50	
 51	/**
 52	 * A single project entry returned in the projects[] array.
 53	 * Derived from ProjectMeta with a curated subset of fields.
 54	 */
 55	interface ProjectEntry {
 56	  slug: string;
 57	  plan_path: string;
 58	  status: string;
 59	  date_created: string;
 60	  last_updated: string;
 61	  title?: string;
 62	  outcome_summary: string | null;
 63	  progress_pct?: number;
 64	}
 65	
 66	/**
 67	 * The full structured response from ledger_get_repository_context.
 68	 */
 69	interface RepositoryContextResponse {
 70	  repository_name: string;
 71	  repository_id: string | null;
 72	  repository_label: string | null;
 73	  total_projects: number;
 74	  strategic_vision: RepositoryEntry['vision'] | null;
 75	  projects: ProjectEntry[];
 76	  relevant_insights: Insight[];
 77	}
 78	
 79	// ─── Handler ──────────────────────────────────────────────────────────────
 80	
 81	async function getRepositoryContext(
 82	  args: z.infer<typeof GetRepositoryContextSchema>
 83	): Promise<{ content: Array<{ type: 'text'; text: string }>; isError?: boolean }> {
 84	  try {
 85	    const ledgerRoot = resolveLedgerRoot();
 86	
 87	    // 1. Resolve repository name
 88	    let repositoryName: string;
 89	    if (args.repository_name) {
 90	      repositoryName = args.repository_name;
 91	    } else if (args.cwd_path) {
 92	      // Derive from the workspace path (same logic as LedgerStore constructor)
 93	      repositoryName = deriveRepoName(
 94	        // deriveRepoName expects a plan folder path — construct a synthetic one
 95	        // that places the repo root 4 levels above cwd_path (the conventional layout)
 96	        `${args.cwd_path}/docs/agents/plans/synthetic-slug`
 97	      );
 98	    } else {
 99	      return {
100	        content: [

101	          {
102	            type: 'text' as const,
103	            text: 'Error: Either cwd_path or repository_name must be provided.',
104	          },
105	        ],
106	        isError: true,
107	      };
108	    }
109	
110	    // 2. Consult the registry for this repository
111	    const registry = await loadRegistry(ledgerRoot);
112	    const registryEntry = findByFolderName(registry, repositoryName);
113	
114	    // 3. Collect folder names to scan
115	    //    - Registry match: scan ALL declared folder_names (cross-folder aggregation)
116	    //    - No registry match: scan only the single derived folder name
117	    const folderNamesToScan: string[] = registryEntry
118	      ? registryEntry.folder_names
119	      : [repositoryName];
120	
121	    // 4. Read projects from the targeted namespace directories only
122	    const allProjects = await LedgerStore.listProjectsByFolderNames(
123	      folderNamesToScan,
124	      ledgerRoot
125	    );
126	
127	    // 5. Sort by date_created descending (most recently created first)
128	    const sorted = [...allProjects].sort((a, b) =>
129	      b.date_created.localeCompare(a.date_created)
130	    );
131	
132	    const totalProjects = sorted.length;
133	
134	    // 6. Apply max_projects cap
135	    const maxProjects = args.max_projects ?? 5;
136	    const capped = sorted.slice(0, maxProjects);
137	
138	    // 7. Map to ProjectEntry shape
139	    const projects: ProjectEntry[] = capped.map((meta: ProjectMeta) => {
140	      const entry: ProjectEntry = {
141	        slug: meta.slug,
142	        plan_path: meta.plan_path,
143	        status: meta.status,
144	        date_created: meta.date_created,
145	        last_updated: meta.last_updated,
146	        outcome_summary: meta.outcome_summary ?? null,
147	      };
148	      if (meta.title !== undefined) {
149	        entry.title = meta.title;
150	      }
151	      if (meta.progress_pct !== undefined) {
152	        entry.progress_pct = meta.progress_pct;
153	      }
154	      return entry;
155	    });
156	
157	    // 8. Query knowledge store for relevant insights (optional)
158	    let relevantInsights: Insight[] = [];
159	    if (args.include_insights !== false) {
160	      const knowledgeManager = new KnowledgeStoreManager(ledgerRoot);
161	      // Query both global and repository-scoped insights
162	      const [globalInsights, repoInsights] = await Promise.all([
163	        knowledgeManager.listInsights({ scope: 'global', limit: 20 }),
164	        safeListRepositoryInsights(knowledgeManager, repositoryName),
165	      ]);
166	      // Deduplicate by insight id (global insights take precedence over repo-scoped)
167	      const seenIds = new Set<number>();
168	      const deduped: Insight[] = [];
169	      for (const insight of [...globalInsights, ...repoInsights]) {
170	        if (!seenIds.has(insight.id)) {
171	          seenIds.add(insight.id);
172	          deduped.push(insight);
173	        }
174	      }
175	      relevantInsights = deduped;
176	    }
177	
178	    // 9. Build the response
179	    const response: RepositoryContextResponse = {
180	      repository_name: repositoryName,
181	      repository_id: registryEntry ? registryEntry.id : null,
182	      repository_label: registryEntry ? registryEntry.label : null,
183	      total_projects: totalProjects,
184	      strategic_vision: registryEntry ? registryEntry.vision : null,
185	      projects,
186	      relevant_insights: relevantInsights,
187	    };
188	
189	    return {
190	      content: [
191	        {
192	          type: 'text' as const,
193	          text: JSON.stringify(response, null, 2),
194	        },
195	      ],
196	    };
197	  } catch (error) {
198	    return {
199	      content: [
200	        {
201	          type: 'text' as const,
202	          text: `Error retrieving repository context: ${(error as Error).message}`,
203	        },
204	      ],
205	      isError: true,
206	    };
207	  }
208	}
